import sys
input = sys.stdin.read

def digit_sum(x):
    return sum(int(d) for d in str(x))

def count_really_big_numbers(n, s):
    left = s
    right = n
    while left <= right:
        mid = (left + right) // 2
        if mid - digit_sum(mid) < s:
            left = mid + 1
        else:
            right = mid - 1
    return n - left + 1

data = input().strip().split()
n = int(data[0])
s = int(data[1])

result = count_really_big_numbers(n, s)
print(result)
